{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish stability across runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure; repeated testing is unspecified. MESA 16: variation across runs is not established."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run provides no evidence about stability across runs."
        }
      ],
      "instrument_review": "MESA 14: No; repeated testing explicitly did not occur. This leaves stability unknown rather than demonstrating unstable scores."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes; repeated testing occurred. The observed variation supports stability under the report's stated criterion for this comparison."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing occurred despite the unfavourable stability results."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability threshold of two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes; testing occurred. The results contradict stability under the report's criterion; whether testing occurred is separate from whether results were favourable."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "No results measuring variation across runs are supplied."
        }
      ],
      "instrument_review": "MESA 14 remains Not sure. Installation guidance is relevant to MESA 22 reproducibility, but supplies no evidence of repeated testing or stability."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A solved more evaluated puzzles under the stated scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results do not establish relative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2 and 25: the stated use fits the observed grid-puzzle comparison. MESA 20: broader performance is not established; no broader intended use is stated."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported evaluation supports A's better performance on these grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use does not supply evidence of general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 9 and 20: grid-only findings do not establish coverage or performance across domains. MESA 25: using these findings to select for general intelligence exceeds the supplied evidence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial with blinded correctness checks and a reported difference interval of 12 to 28 percentage points supports better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an unmeasured safety benefit."
        }
      ],
      "instrument_review": "MESA 20: the later trial supplies evidence beyond initial test scores for correctness in this workshop. MESA 16: uncertainty for that difference is reported. MESA 25: conclusions should remain limited to correctness in the studied conditions."
    }
  ],
  "closing_note": "No unresolved instruction ambiguity. Probe labels classify statement support; missing evidence does not establish contradiction."
}
